mapper.update:
UPDATE stock_order 
SET status = 'CANCEL', 
    updated_at = NOW()
WHERE order_id = #{orderId} 
  AND account_id = #{accountId}
  AND status IN ('WAIT', 'PARTIAL')

mapper.select:
SELECT SUM(o.quantity - COALESCE(t.exec_sum, 0))
FROM stock_order o
LEFT JOIN (
    SELECT order_id, SUM(trade_quantity) as exec_sum
    FROM trade_log 
    GROUP BY order_id
) t ON o.order_id = t.order_id
WHERE o.account_id = #{accountId}
  AND o.stock_code = #{stockCode}
  AND o.transaction_type = #{type}
  AND o.status IN ('WAIT', 'PARTIAL')
